import assert from "node:assert/strict";
import { test } from "node:test";
import { analysisInputHash } from "../lib/matching-input.mjs";

test("manual matching and backfill use the PostgreSQL automatic-matching cache key", () => {
  // Independently generated by PostgreSQL 17 md5(jsonb_build_object(...)::text).
  const input = ["sample-cv", "00000000-0000-4000-8000-000000000001", "Responsibilities: develop Python.\nQualifications: SQL and machine learning.", "gemini-3.5-flash", "v1"];
  assert.equal(analysisInputHash(...input), "4c0409bad6d5679d6bd99a4d451a9222");
  const original = analysisInputHash(...input);
  for (let index = 0; index < input.length; index++) {
    const changed = [...input];
    changed[index] += " changed";
    assert.notEqual(analysisInputHash(...changed), original);
  }
});
